func TestGetHookConfigPath(t *testing.T) {
	ag := &GeminiCLIAgent{}
	path := ag.GetHookConfigPath()
	if path != ".gemini/settings.json" {
		t.Errorf("GetHookConfigPath() = %q, want .gemini/settings.json", path)
